#include "decomp_annotations.h"
#include "KS/SRC/vm_thread_shared.h"

void vm_thread::create_event_callback(const argument_t &arg, bool one_shot)
{
    script_object::instance *local_inst =
        (script_object::instance *)dstack.pop_addr();
    if (local_inst == NULL ||
        (uint32)local_inst == UNINITIALIZED_SCRIPT_PARM)
    {
        slf_error("(local) event callback " + arg.sfr->get_fullname() +
                  ": invalid local script object instance pointer");
    }
    dstack.pop(arg.sfr->get_parms_stacksize());
    char *parms = dstack.get_SP();
    vm_signal_t v = dstack.pop_signal();
    v->add_callback(local_inst, arg.sfr, parms, one_shot);
}
